    ('amazon-ebs', 'discos-ebs-orfaos-sem-instancia-conectada-unattached-volumes', 'caution', 1,
        'Não exclua por estado isolado', 'Um volume desanexado pode conter dados necessários; snapshots mantidos também continuam sujeitos a cobrança.'),

    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway', 'check', 1,
        'Confirme o caminho', 'Revise tabelas de rotas e métricas de bytes do NAT para identificar destinos AWS e volume transferido.'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway', 'check', 2,
        'Confira região e sub-rede', 'Verifique se os serviços acessados estão na região esperada e quais sub-redes precisam de acesso privado.'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway', 'action', 1,
        'Avalie Gateway Endpoints', 'Para S3 e DynamoDB, avalie endpoints de gateway e atualize as tabelas de rotas pertinentes; valide conectividade e políticas.'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway', 'caution', 1,
        'Compare todos os componentes', 'Endpoint de gateway não tem cobrança horária, mas valide a arquitetura completa; outros tipos de endpoint podem ter preço diferente.'),

    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning', 'check', 1,
        'Observe invocações reais', 'Compare duração, memória máxima usada, erros e concorrência em execuções representativas; inclua períodos de pico.'),
    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning', 'check', 2,
        'Meça antes de alterar', 'Use AWS Lambda Power Tuning ou testes controlados para comparar configurações de memória e duração da função.'),
    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning', 'action', 1,
        'Ajuste e valide', 'Teste uma configuração por vez e compare custo, latência e resultados funcionais antes de publicar a alteração.'),
    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning', 'caution', 1,
