INSERT INTO scenario_sources (scenario_id, title, url)
SELECT scenario.id, source.title, source.url
FROM (VALUES
    ('amazon-eks', 'superdimensionamento-de-nos-do-cluster-node-over-provisioning',
        'EKS Best Practices: Compute and Autoscaling', 'https://docs.aws.amazon.com/eks/latest/best-practices/cost-opt-compute.html'),
    ('amazon-dynamodb', 'dimensionamento-de-capacidade-provisionada-sem-auto-scaling-provisioned-throughput',
        'DynamoDB: Evaluate your table capacity mode', 'https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/CostOptimization_TableCapacityMode.html'),
    ('amazon-rds', 'ambientes-de-desenvolvimento-e-homologacao-rodando-24-7',
        'RDS: Stopping an Amazon RDS DB instance temporarily', 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_StopInstance.html'),
    ('amazon-rds', 'ambientes-de-desenvolvimento-e-homologacao-rodando-24-7',
        'RDS: Introduction to backups', 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html'),
    ('amazon-s3', 'manutencao-de-todos-os-arquivos-na-classe-s3-standard-24-7',
        'S3: Managing the lifecycle of objects', 'https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lifecycle-mgmt.html'),
    ('amazon-ebs', 'discos-ebs-orfaos-sem-instancia-conectada-unattached-volumes',
        'Amazon EBS volume types and characteristics', 'https://docs.aws.amazon.com/ebs/latest/userguide/ebs-volume-types.html'),
    ('amazon-ebs', 'discos-ebs-orfaos-sem-instancia-conectada-unattached-volumes',
        'Amazon EBS pricing', 'https://aws.amazon.com/ebs/pricing/'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway',
        'NAT gateway pricing and data transfer strategies', 'https://docs.aws.amazon.com/vpc/latest/userguide/nat-gateway-pricing.html'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway',
        'Gateway endpoints for Amazon S3 and DynamoDB', 'https://docs.aws.amazon.com/vpc/latest/privatelink/gateway-endpoints.html'),
    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning',
        'Lambda: Configure memory', 'https://docs.aws.amazon.com/lambda/latest/dg/configuration-memory.html')
) AS source(service_slug, scenario_slug, title, url)
JOIN aws_services AS service ON service.slug = source.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = source.scenario_slug
ON CONFLICT (scenario_id, url) DO UPDATE
SET title = EXCLUDED.title,
    reviewed_at = CURRENT_DATE;

