        'Confirme as limitações da topologia', 'Gateway endpoints para S3 não têm cobrança adicional, mas não atendem todos os cenários, como acesso de redes on-premises ou de VPCs emparelhadas em outras regiões.'),

    ('amazon-ebs', 'provisionamento-excessivo-de-iops-em-discos-de-alto-desempenho-io1-io2', 'check', 1,
        'Meça a necessidade do volume', 'Compare IOPS e throughput provisionados com utilização, latência e filas durante horários de maior carga.'),
    ('amazon-ebs', 'provisionamento-excessivo-de-iops-em-discos-de-alto-desempenho-io1-io2', 'check', 2,
        'Analise opções e risco', 'Use recomendações do Compute Optimizer, preços estimados e risco de desempenho; o serviço analisa até 14 dias de métricas por padrão.'),
    ('amazon-ebs', 'provisionamento-excessivo-de-iops-em-discos-de-alto-desempenho-io1-io2', 'action', 1,
        'Valide uma configuração alternativa', 'Teste o tipo e a capacidade recomendados com carga representativa e acompanhe latência e desempenho após a alteração.'),
    ('amazon-ebs', 'provisionamento-excessivo-de-iops-em-discos-de-alto-desempenho-io1-io2', 'caution', 1,
        'Não reduza IOPS sem teste', 'IOPS insuficientes podem degradar operações de banco de dados ou outras aplicações sensíveis à latência; preserve requisitos de pico.'),

    ('amazon-cloudwatch', 'falta-de-definicao-de-politicas-de-retencao-retention-period-em-log-groups', 'check', 1,
        'Identifique grupos sem expiração', 'Liste log groups sem retenção definida e classifique ambiente, volume, finalidade operacional e requisitos de auditoria.'),
    ('amazon-cloudwatch', 'falta-de-definicao-de-politicas-de-retencao-retention-period-em-log-groups', 'check', 2,
        'Confirme o prazo obrigatório', 'Consulte as equipes de segurança, risco e compliance antes de definir por quanto tempo cada categoria de log deve ser mantida.'),
    ('amazon-cloudwatch', 'falta-de-definicao-de-politicas-de-retencao-retention-period-em-log-groups', 'action', 1,
        'Configure retenção por grupo', 'Defina um período apropriado para cada log group e valide as políticas aplicadas, inclusive eventuais políticas no nível da conta.'),
    ('amazon-cloudwatch', 'falta-de-definicao-de-politicas-de-retencao-retention-period-em-log-groups', 'caution', 1,
        'Proteja evidências e auditoria', 'Eventos que atingem a retenção são marcados para exclusão e não devem ser tratados como arquivo permanente; valide obrigações legais antes de reduzir prazos.'),

    ('amazon-cloudfront', 'servindo-arquivos-estaticos-direto-do-s3-ec2-sem-cache', 'check', 1,
        'Meça o cache atual', 'Revise cache hit ratio, comportamento por caminho e quantidade de solicitações que ainda chegam à origem.'),
    ('amazon-cloudfront', 'servindo-arquivos-estaticos-direto-do-s3-ec2-sem-cache', 'check', 2,
        'Separe conteúdo estático e privado', 'Identifique objetos estáticos e versionados que podem ser armazenados em cache sem expor conteúdo personalizado ou dados financeiros.'),
    ('amazon-cloudfront', 'servindo-arquivos-estaticos-direto-do-s3-ec2-sem-cache', 'action', 1,
        'Ajuste a política de cache', 'Teste TTLs e chaves de cache para conteúdo estático e compare solicitações à origem, latência e custos após a mudança.'),
    ('amazon-cloudfront', 'servindo-arquivos-estaticos-direto-do-s3-ec2-sem-cache', 'caution', 1,
        'Não prometa economia sem medir', 'Cache reduz solicitações que chegam à origem, mas o efeito no custo total depende do tráfego, da distribuição e dos preços aplicáveis.')
) AS step(service_slug, scenario_slug, step_type, position, title, content)
JOIN aws_services AS service ON service.slug = step.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = step.scenario_slug
ON CONFLICT (scenario_id, step_type, position) DO UPDATE
SET title = EXCLUDED.title,
    content = EXCLUDED.content;

